UPDATE companies SET description='Custom Manufacturing Services, Inc. (CMS) and East River Metals, Inc. (ERM) operate from three facilities in Princeton, West Virginia, and Rocky Gap, Virginia. The business traces its roots to 1979 when Bob Graf founded East River Metals to produce metal enclosures for its sister company, American Mine Research. In 1995, Graf established Custom Manufacturing Services to combine ERM''s sheet metal expertise with American Mine Research''s electro-mechanical assembly capabilities.

The two entities together provide precision sheet metal fabrication, turnkey electro-mechanical assembly, and powder and wet spray coating. Core processes include laser cutting, forming, welding, hardware insertion, and outsourced plating. The combined footprint spans more than 155,000 square feet of manufacturing, office, and warehouse space across the two states.

Customers span mining, aerospace and defense, electronics, food processing, industrial machinery, and oil and gas. Named clients include American Mine Research, Moog, Pascor Atlantic, Forensic Computers, JBS, Caron, and Smyth Co. Machine.

The company emphasizes complete in-house control over fabrication, assembly, and finishing to deliver quick turnarounds and consistent quality. Its quality policy targets exceeding customer expectations, supported by ISO 9001:2015 certification and statistical process controls such as CpK studies and FMEA.', certifications=ARRAY['ISO 9001:2015']::text[], profile='{"capabilities": ["Precision sheet metal fabrication", "Laser cutting", "Forming and bending", "Welding", "Hardware insertion", "Powder coating", "Wet spray coating", "Electro-mechanical assembly", "Turnkey electro-mechanical assembly", "Plating (outsourced)", "FMEA", "Process flow charting", "Process control plans", "CpK studies", "Pre-production approval", "Process mapping", "Control charting", "Part certification", "Micro-Vu vision measuring"], "industries": ["Mining", "Aerospace and defense", "Electronics", "Food processing", "Industrial machinery", "Oil and gas"], "materials": ["Aluminum", "Steel", "Stainless steel"], "equipment": ["Micro-Vu Model 324 Vision Measuring System", "Amada laser/punch system", "Automated wire crimping machine", "Combi combination machine"], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Complete in-house control over fabrication, assembly, and finishing", "Quick turnarounds supported by 155,000+ sq. ft. across three facilities", "ISO 9001:2015 certified quality system with CpK and FMEA", "Turnkey electro-mechanical assembly integrated with precision sheet metal work"], "facts_used": ["Founded 1979 by Bob Graf -> /", "CMS founded 1995 -> /", "Family-led, David Graf president -> /", "Three facilities, 155,000+ sq ft -> /", "ISO 9001:2015 certified -> /quality", "Materials: aluminum, steel, stainless steel -> /services", "Processes: laser cutting, powder coat, wet spray, turnkey electro-mechanical assembly -> /services", "Customers: AMR, Moog, Pascor Atlantic, Forensic Computers, JBS, Caron, Smyth Co. Machine -> /", "Equipment: Micro-Vu Model 324, Amada, automated wire crimping, Combi -> /quality, /", "Quality methods: FMEA, CpK, control charting -> /quality"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Since 1979, Custom Manufacturing Services, Inc. (CMS) and East River Metals (ERM) have manufactured metal enclosures, precision fabricated metal parts and weldments and electro-mechanical assemblies.", "founded_year": "1979", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='custom-manufacturing-services-inc' AND approved AND profile IS NULL;
UPDATE companies SET description='Custom Metal Products operates from Albuquerque, New Mexico, where it was established in 1988 after Steve and Cheryl Ryan purchased the business from a previous father‑son ownership. The Ryans built the company while Steve worked as a hotshot driver, and their son Keith later learned the trade before teaching Alan Cofran to run the operation in 1998. Today the business continues as a family‑owned enterprise, with Cofran at the helm alongside his son A.J. and longtime associate Josh, maintaining the legacy on Vassar Place Northeast.

The shop specializes in custom sheet metal fabrication, cutting and bending mild steel from 29‑gauge to 16‑gauge and stainless steel up to 22‑gauge. A Berridge T‑panel machine adds radius‑forming capability for Berridge‑brand panels. The company also supplies sheet metal screws and clips and handles trim work in galvanized, copper and aluminum.

Its flexibility in accepting customer‑supplied material and its willingness to work early, late or weekend hours by arrangement make it a practical extension of a client’s own fabrication capacity.

