UPDATE companies SET description='Cycle Gear operates a chain of motorcycle gear and accessories retail stores headquartered in Albuquerque, New Mexico. The company runs over 170 locations across the United States. The retailer stocks over 100,000 products including helmets, riding apparel, boots, gloves, parts, tires, and accessories for motorcycles, UTVs, and ATVs. Each location also hosts community events like bike nights. Cycle Gear serves street, cruiser, dirt, adventure, and touring riders, as well as UTV and ATV owners. The inventory features brands such as Shoei, Arai, AGV, Bell, Scorpion, HJC, Icon, Alpinestars, and its own SEDICI label. The RPM membership program provides cash-back rewards and referral discounts to frequent shoppers.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Retail sales of motorcycle gear and parts", "In-store customer support", "Free ship-to-store pickup", "Tire installation", "Bluetooth communicator installation", "Community event hosting (bike nights)", "Loyalty program management"], "industries": ["Motorcycle", "UTV/ATV"], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": [], "facts_used": ["Headquarters in Albuquerque, New Mexico -> db", "Over 170 stores nationwide -> /", "Free shipping to store for pickup -> /", "Experienced staff support on site -> /", "Bike Nights community events -> /", "Tire installation service -> /", "Bluetooth communicator installation -> /", "Carries brands Shoei, Arai, AGV, Bell, Scorpion, HJC, Icon, Alpinestars, SEDICI -> /", "Serves motorcycle, UTV/ATV riders -> /", "RPM membership cash-back program -> /"], "company_type": "Retailer", "makes_products": "no", "type_evidence": "Over 170 Stores!", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='cycle-gear' AND approved AND profile IS NULL;
UPDATE companies SET description='Cyril''s Foods operates from Fort Lauderdale, Florida. The company''s founding year and ownership details are not publicly disclosed. It began as an innovative bakery company focused on creating distinctive products for foodservice channels.

The company produces three core product lines: cake pops made with 100% real chocolate and shaped into consistent spheres; gourmet toaster pastries featuring flaky crusts, indulgent fillings, and delicate icing; and cheesy egg & potato waffles composed of equal parts shredded potatoes, cheddar cheese, and eggs, with chives. The waffles are marketed as gluten-free, low-carb, and keto-friendly. Production includes foodservice bulk packing and foodservice packing capabilities.

Cyril''s Foods supplies coffee shops, convenience stores, and in-store bakeries. Its cake pops have been adopted by a 600-unit coffee chain where the Birthday Cake flavor became a top seller, and by a 60-unit coffee chain that called the launch the most successful product introduction in its history.

